		/** 
		 * Tests creating a new Channel.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Channel");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Channel" );

			try {            
				Channel entity = ChannelService.getChannelInstance().createChannel( generateNewEntity() );
				thePrimaryKey = entity.getChannelId();
				LOGGER.info( "-- Successfully created a Channel with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Channel. 
		 */
		public Channel testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Channel" );

			Channel entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Channel with primary key" );
			msg.append( thePrimaryKey );
			
			ChannelFetchOneSummary fetchOneSummary = new ChannelFetchOneSummary( thePrimaryKey );

			try {
				entity = ChannelService.getChannelInstance().getChannel( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Channel " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Channel.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Channel." );

			StringBuilder msg = new StringBuilder( "Failed to update a Channel : " );        
			Channel entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Channel." );

				// for use later on...
				thePrimaryKey = entity.getChannelId();

				ChannelService proxy = ChannelService.getChannelInstance();            
				proxy.updateChannel( entity );   

				LOGGER.info( "-- Successfully saved Channel - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Channel.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Channel." );

			try{
			    Channel entity = testRead(); 
				ChannelService.getChannelInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Channel with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Channel with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Channels.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Channels:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Channel : " );        
			List<Channel> collection  = null;

			try {
				// call the static get method on the ChannelService
				collection = ChannelService.getChannelInstance().getAllChannel();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Channel entity = null;            
					Iterator<Channel> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getChannelId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

